'use client';
import { useState } from 'react';
import Link from 'next/link';
import { ArrowUpRight, ArrowRight, Code2 } from 'lucide-react';
import { motion, useReducedMotion } from 'motion/react';
import { projects } from '@/content/projects';
import { ProjectVisual } from './project-visual';
import { Dialog, DialogTrigger, DialogContent, DialogTitle, DialogDescription } from './ui/dialog';
import { Button } from './ui/button';
export function Work(){const reduced=useReducedMotion();return <div className="project-grid">{projects.map((p,i)=><article className={'project-card reveal project-'+p.slug} key={p.slug}><Dialog><DialogTrigger asChild><motion.button className="project-preview" aria-label={'View '+p.name+' project details'} whileHover={reduced?{}:{y:-5}} transition={{duration:.35}}><ProjectVisual slug={p.slug}/><span className="project-hover">Explore project <ArrowUpRight size={20}/></span><span className="project-no">/{p.number}</span></motion.button></DialogTrigger><DialogContent><span className="eyebrow">SELECTED WORK / {p.number}</span><DialogTitle className="dialog-title">{p.name}</DialogTitle><DialogDescription className="dialog-description">{p.description}</DialogDescription><ProjectVisual slug={p.slug}/><p className="dialog-overview">{p.overview}</p><div className="tag-list">{p.focus.map(f=><span key={f}>{f}</span>)}</div><div className="dialog-actions"><Button asChild><a href={p.url} target="_blank" rel="noreferrer">Visit live site <ArrowUpRight size={16}/></a></Button><Button variant="outline" asChild><Link href={'/work/'+p.slug}>Project overview <ArrowRight size={16}/></Link></Button><a className="source-link" href={p.repo} target="_blank" rel="noreferrer" aria-label={'View '+p.name+' source on GitHub'}><Code2 size={20}/></a></div></DialogContent></Dialog><div className="project-caption"><div><Link href={'/work/'+p.slug}><h3>{p.name}<ArrowUpRight size={22}/></h3></Link><p>{p.description}</p></div><span>{p.category}</span></div></article>)}</div>}
